CREATE FUNCTION public.billing_projection(_appointment uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.appointments; s jsonb; result jsonb; BEGIN IF NOT public.is_aal2() OR NOT public.has_permission('billing.till') THEN RAISE EXCEPTION 'Geen toegang.'; END IF; SELECT * INTO a FROM public.appointments WHERE id=_appointment AND tenant_id=public.current_tenant(); IF NOT FOUND THEN RAISE EXCEPTION 'Afspraak niet gevonden.'; END IF; SELECT step_data INTO s FROM public.consult_notes WHERE tenant_id=a.tenant_id AND appointment_id=a.id ORDER BY created_at DESC LIMIT 1; SELECT coalesce(jsonb_agg(jsonb_build_object('treatmentId',l->>'treatmentId','qty',l->'qty','unit',l->>'unit','priceCents',l->'priceCents')), '[]'::jsonb) INTO result FROM jsonb_array_elements(CASE WHEN jsonb_typeof(s->'lines')='array' THEN s->'lines' ELSE '[]'::jsonb END) l; RETURN jsonb_build_object('lines',result,'exempt',coalesce((s->'vat'->>'exempt')::boolean,false) AND coalesce(s->'vat'->>'by','')<>'' AND coalesce(s->'vat'->>'at','')<>''); END $$; REVOKE ALL ON FUNCTION public.billing_projection(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.billing_projection(uuid) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.settle_appointment(uuid,jsonb,jsonb,boolean,text)'::regprocedure) INTO d; d:=replace(d,$old$SELECT jsonb_build_object('clinic',display_name,'legal',legal,'demo',test_mode)$old$,$new$SELECT jsonb_build_object('clinic',display_name,'demo',test_mode)$new$); EXECUTE d; END $$;